import{_ as a,o as t,c as o,a2 as e}from"./chunks/framework.BZO4qERu.js";const _=JSON.parse('{"title":"文献综述","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/reviews.md","filePath":"zh/guide/reviews.md","lastUpdated":1792570296000}'),n={name:"zh/guide/reviews.md"};function s(p,r,i,g,l,h){return t(),o("div",null,[...r[0]||(r[0]=[e('<h1 id="文献综述" tabindex="-1">文献综述 <a class="header-anchor" href="#文献综述" aria-label="Permalink to &quot;文献综述&quot;">​</a></h1><p><strong>实验性功能。</strong> 将选定文献的摘要证据组织成主题大纲，生成可编辑且带引用的草稿。</p><p>该功能使用已有论文与摘要，不会自动读取完整 PDF。请对照原始研究核查草稿。</p><h2 id="模块与证据" tabindex="-1">模块与证据 <a class="header-anchor" href="#模块与证据" aria-label="Permalink to &quot;模块与证据&quot;">​</a></h2><p>综述包含文献、大纲、正文和引用证据四个子页。当前综述的模型配置在综述页的模型折叠区中调整，生成期间不能修改。历史侧栏只显示综述；引用证据集中提供段落引文与文献关系图。新综述独立保存可用的来源图快照，旧综述仍可能依赖来源检索。</p><h2 id="_1-选择检索" tabindex="-1">1. 选择检索 <a class="header-anchor" href="#_1-选择检索" aria-label="Permalink to &quot;1. 选择检索&quot;">​</a></h2><p>从结果勾选后进入，或打开<strong>综述 → 新建综述</strong>，选择已有检索。</p><p>在线综述需要登录和已保存的来源检索；社区版保存在本地。</p><h2 id="_2-设置范围" tabindex="-1">2. 设置范围 <a class="header-anchor" href="#_2-设置范围" aria-label="Permalink to &quot;2. 设置范围&quot;">​</a></h2><p>填写主题，选择中文或英文、写作模型，以及简短、标准或详细。</p><p>默认章节数分别为 <strong>1、3、6</strong>，可自定义 <strong>1–14 章</strong>。这不保证固定字数，证据与大纲决定了适合写作的内容。</p><p>展开<strong>更多选项</strong>，可以设置每章段落数和每段目标长度。自动段落数随篇幅调整，自定义范围是<strong>每章 1–10 段</strong>。中文输出的自定义长度为每段 <strong>100–1,500 字</strong>，英文为每段 <strong>50–800 词</strong>。这些是写作目标，仍需检查生成的大纲和正文。</p><p>社区版和在线版自带密钥模式可以配置写作模型，PaperSeek 服务从允许的模型中选择。</p><h2 id="_3-选择文献" tabindex="-1">3. 选择文献 <a class="header-anchor" href="#_3-选择文献" aria-label="Permalink to &quot;3. 选择文献&quot;">​</a></h2><p>篇幅决定建议选用的文献数量：简短约 <strong>8–20 篇</strong>，标准约 <strong>20–45 篇</strong>，详细约 <strong>40–80 篇</strong>；自定义章节或段落时按段落数估算。手动选择可以来自全部检索结果，上限为 <strong>256 篇</strong>，不必选满。</p><p>可以手动勾选，也可以点击<strong>按主题自动挑选</strong>：写作模型从按检索排名排列的前 <strong>256 篇有有效摘要的文献</strong>中，挑出覆盖不同主题、方法和研究对象的文献，并给出每篇的挑选理由。挑选结果仍可增删，包括手动加入排名更后的文献。自动挑选不计入写作次数，使用 PaperSeek 服务时也不扣积分。</p><p>只能选择有摘要的文献。文献更多不代表证据更好，缺乏有效研究内容的记录可能不会参与正文。</p><p>自动挑选期间可以切换到其他模块。返回综述后，从侧栏的<strong>挑选中 / 待确认</strong>草稿继续，写作设置、已选论文和理由都会保留。当前标签页只保留一份待确认草稿；刷新、关闭页面或退出账号会清空。<strong>停止等待</strong>会忽略后续返回的挑选结果，但不保证中断模型端已经开始的计算；<strong>丢弃草稿</strong>会清空这份草稿。</p><h2 id="_4-检查大纲" tabindex="-1">4. 检查大纲 <a class="header-anchor" href="#_4-检查大纲" aria-label="Permalink to &quot;4. 检查大纲&quot;">​</a></h2><p>审阅主题、章节结构、段落计划和文献分配，检查遗漏视角及超出证据的写作范围。</p><p>生成的段落计划最多分配 <strong>10 篇</strong>文献。大纲用不上的文献会列在<strong>未纳入大纲的文献</strong>中，并附上不纳入的理由。要重新纳入，在某一章的支撑文献里添加即可，该文献随后会从排除列表移除；从所有章节移除的文献会自动记为手动移除。</p><p>点击<strong>保存大纲</strong>只保存修改，不启动写作；准备好生成正文后，再点击<strong>确认大纲并执行</strong>或<strong>保存大纲并执行</strong>。离开未保存的编辑时，会提示继续编辑或放弃修改。</p><h2 id="_5-阅读与修订" tabindex="-1">5. 阅读与修订 <a class="header-anchor" href="#_5-阅读与修订" aria-label="Permalink to &quot;5. 阅读与修订&quot;">​</a></h2><p>可以编辑文字、单节重写并查看可用版本。修改大纲不会自动让旧正文与新大纲一致，应检查当前版本和任务状态。</p><p>引文可选择顺序编号或 Harvard 作者—年份，导出沿用所选呈现方式。</p><p>写作时，模型可以不引用某篇计划文献，但要说明理由，例如与本段比较的问题无关或与另一项研究重复。每章末尾的<strong>未引用的计划文献</strong>列出这些文献和理由；证据核对认为理由可能不成立时会标出，并说明依据。</p><p>某条排除理由无法完成核对时，会保留正文，并标记“排除理由检查未完成”，由你人工核对。检查未完成不表示该理由已获认可。</p><p>段落中引用了、但没能对应到具体论断的文献，会单独列在该段下方的<strong>未对应到具体论断的引用</strong>中，导出时同样保留。</p><p>证据检查能提示支撑不足或不一致，但不能证明科学结论正确。依赖论断前仍需阅读原始论文。</p><p>证据引文保留摘要原文及其语言，即使正文使用另一种语言也不改变。无法可靠定位更短的支撑片段时，引文可能较长；请核对它是否确实支持对应观察。不能在摘要中验证的文字不会作为可用证据。</p><h2 id="_6-导出" tabindex="-1">6. 导出 <a class="header-anchor" href="#_6-导出" aria-label="Permalink to &quot;6. 导出&quot;">​</a></h2><ul><li><strong>Markdown</strong>：继续编辑。</li><li><strong>Word（.docx）</strong>：文档写作。</li><li><strong>BibTeX</strong>：管理参考文献。</li></ul><h2 id="生成中断时" tabindex="-1">生成中断时 <a class="header-anchor" href="#生成中断时" aria-label="Permalink to &quot;生成中断时&quot;">​</a></h2><p>当前或最近任务的状态与已保存正文分开展示，停止任务不会抹除大纲或已经完成的章节。模型访问、余额、超时和结构化响应错误可能导致大纲或正文中断。修正原因后重试受影响操作，不必创建重复综述。</p><p>刷新连接已保存状态，不会重启生成。在线写作与检索共用<a href="./../online/#任务排队">执行队列</a>。</p>',35)])])}const c=a(n,[["render",s]]);export{_ as __pageData,c as default};
